package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

const generatedHeader = "Generated by `just gen` from project.yaml files. Do not edit."

// Generated files, relative to the repo root.
const (
	composeFile = "compose.projects.yml"
	infraFile   = "infra/projects.json"
)

// Generate renders every generated file.
func Generate(r *Repo) (map[string][]byte, error) {
	infra, err := genInfra(r)
	if err != nil {
		return nil, err
	}
	return map[string][]byte{
		composeFile: genCompose(r),
		infraFile:   infra,
	}, nil
}

// WriteGenerated writes the generated files, or with check only reports
// which are out of date.
func WriteGenerated(r *Repo, check bool) error {
	files, err := Generate(r)
	if err != nil {
		return err
	}
	var stale []string
	for _, name := range sortedKeys(files) {
		path := filepath.Join(r.Root, name)
		current, _ := os.ReadFile(path)
		if bytes.Equal(current, files[name]) {
			continue
		}
		if check {
			stale = append(stale, name)
			continue
		}
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(path, files[name], 0o644); err != nil {
			return err
		}
		fmt.Fprintf(os.Stderr, "wrote %s\n", name)
	}
	if len(stale) > 0 {
		return fmt.Errorf("generated files are out of date: %s (run `just gen`)", strings.Join(stale, ", "))
	}
	return nil
}

func devDatabaseURL(name string) string {
	return fmt.Sprintf("postgresql://postgres:postgres@postgres:5432/%s?sslmode=disable", name)
}

func genCompose(r *Repo) []byte {
	var b strings.Builder
	w := func(indent int, format string, args ...any) {
		b.WriteString(strings.Repeat("  ", indent))
		fmt.Fprintf(&b, format, args...)
		b.WriteByte('\n')
	}
	fmt.Fprintf(&b, "# %s\n#\n# One container per project; `just up <name>` starts it with everything it\n# depends on. Included by compose.yml.\n", generatedHeader)
	w(0, "services:")

	apps := r.OfKind(KindSvelteApp)
	var origins []string
	for _, a := range apps {
		origins = append(origins, fmt.Sprintf("http://localhost:%d", a.Port))
	}

	for _, p := range r.OfKind(KindGoService) {
		w(1, "%s:", p.Name)
		w(2, "image: laurel-go-dev")
		w(2, "build: { context: ., dockerfile: docker/go-dev.Dockerfile }")
		w(2, "command: [dev-go, %s]", p.Name)
		w(2, "env_file:")
		w(3, "- dev.env")
		w(3, "- { path: %s/.env, required: false }", p.Dir)
		env := map[string]string{}
		if p.Database {
			env["DATABASE_URL"] = devDatabaseURL(p.Name)
			env["AUTO_MIGRATE"] = `"true"`
		}
		if p.Deploy != nil && p.Deploy.Public {
			env["ALLOWED_ORIGINS"] = strings.Join(origins, ",")
		}
		if len(env) > 0 {
			w(2, "environment:")
			for _, k := range sortedKeys(env) {
				w(3, "%s: %s", k, env[k])
			}
		}
		if p.Deploy != nil && p.Deploy.Public {
			w(2, "ports:")
			w(3, `- "8080:8080"`)
		}
		w(2, "volumes:")
		w(3, "- .:/src")
		w(3, "- go_mod:/go/pkg/mod")
		w(3, "- go_build:/root/.cache/go-build")
		if p.Database || len(p.Calls) > 0 {
			w(2, "depends_on:")
			if p.Database {
				w(3, "%s-db: { condition: service_completed_successfully }", p.Name)
			}
			for _, c := range p.Calls {
				w(3, "%s: { condition: service_started }", c)
			}
		}
		w(2, "restart: unless-stopped")
		if p.Database {
			w(1, "%s-db:", p.Name)
			w(2, "extends: { file: compose.db.yml, service: create-database }")
			w(2, "environment: { DB_NAME: %s }", p.Name)
			w(2, "depends_on: { postgres: { condition: service_healthy } }")
		}
		b.WriteByte('\n')
	}

	edge := ""
	for _, p := range r.OfKind(KindGoService) {
		if p.Deploy != nil && p.Deploy.Public {
			edge = p.Name
		}
	}
	for _, a := range apps {
		w(1, "%s:", a.Name)
		w(2, "build: { context: ., dockerfile: docker/svelte-dev.Dockerfile, args: { APP: %s } }", a.Name)
		w(2, "image: laurel-%s-dev", a.Name)
		w(2, "ports:")
		w(3, `- "%d:%d"`, a.Port, a.Port)
		w(2, "env_file:")
		w(3, "- { path: %s/.env, required: false }", a.Dir)
		w(2, "environment:")
		w(3, "NODE_ENV: development")
		w(3, `PORT: "%d"`, a.Port)
		w(3, "API_URL: http://localhost:8080")
		w(2, "volumes:")
		w(3, "- .:/repo")
		// node_modules stay the container's own (Linux binaries).
		w(3, "- /repo/node_modules")
		for _, dir := range tsWorkspaceDirs(r) {
			w(3, "- /repo/%s/node_modules", dir)
		}
		if edge != "" {
			w(2, "depends_on: [%s]", edge)
		}
		w(2, "restart: unless-stopped")
		b.WriteByte('\n')
	}

	w(0, "volumes:")
	w(1, "# Shared by every Go service.")
	w(1, "go_mod: { name: laurel-go-mod }")
	w(1, "go_build: { name: laurel-go-build }")
	return []byte(b.String())
}

// tsWorkspaceDirs lists every pnpm workspace package directory.
func tsWorkspaceDirs(r *Repo) []string {
	ws, err := loadWorkspace(r.Root)
	if err != nil {
		return nil
	}
	return slices.Sorted(func(yield func(string) bool) {
		for _, pkg := range ws.packages {
			if !yield(pkg.Dir) {
				return
			}
		}
	})
}

type infraService struct {
	Database bool              `json:"database"`
	Public   bool              `json:"public"`
	CPU      int               `json:"cpu"`
	Memory   int               `json:"memory"`
	Count    int               `json:"count"`
	Calls    []string          `json:"calls"`
	Secrets  []string          `json:"secrets"`
	Env      map[string]string `json:"env"`
}

type infraApp struct {
	Subdomain string `json:"subdomain"`
}

func genInfra(r *Repo) ([]byte, error) {
	services := map[string]infraService{}
	for _, p := range r.OfKind(KindGoService) {
		d := Deploy{CPU: 256, Memory: 512, Count: 2}
		if p.Deploy != nil {
			d.Public = p.Deploy.Public
			if p.Deploy.CPU != 0 {
				d.CPU = p.Deploy.CPU
			}
			if p.Deploy.Memory != 0 {
				d.Memory = p.Deploy.Memory
			}
			if p.Deploy.Count != 0 {
				d.Count = p.Deploy.Count
			}
		}
		services[p.Name] = infraService{
			Database: p.Database,
			Public:   d.Public,
			CPU:      d.CPU,
			Memory:   d.Memory,
			Count:    d.Count,
			Calls:    orEmpty(p.Calls),
			Secrets:  orEmpty(p.Secrets),
			Env:      orEmptyMap(p.Env),
		}
	}
	apps := map[string]infraApp{}
	for _, p := range r.OfKind(KindSvelteApp) {
		apps[p.Name] = infraApp{Subdomain: p.Subdomain}
	}
	out, err := json.MarshalIndent(map[string]any{
		"_comment": generatedHeader,
		"services": services,
		"apps":     apps,
	}, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(out, '\n'), nil
}

func orEmpty(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

func orEmptyMap(m map[string]string) map[string]string {
	if m == nil {
		return map[string]string{}
	}
	return m
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	return keys
}
